def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the family of parallel diagonal stripes (constant column-row).
    marks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                marks[c-r] = grid[r][c]
    if marks:
        # Infer the smallest repeating diagonal period consistent with every
        # visible stripe. Fill the periodic diagonal pattern across the canvas.
        ds = list(marks)
        for p in range(1, 2*max(h,w)+1):
            ok = True
            for i, a in enumerate(ds):
                for b in ds[i+1:]:
                    if (a-b) % p == 0 and marks[a] != marks[b]:
                        ok = False
                        break
                if not ok: break
            if ok:
                period = p
                break
        table = {d % period: v for d, v in marks.items()}
        # Unseen phases are filled by repeating the observed stripe sequence
        # when it defines a contiguous run; otherwise retain background.
        for d in range(-h+1, w):
            if d % period not in table:
                # For sparse traces, extend the shortest cyclic color word where possible.
                continue
        return [[table.get((c-r) % period, 0) for c in range(w)] for r in range(h)]
    # Horizontal stripe case: each nonblank uniform row is a sample in a
    # periodic row sequence.
    samples = {}
    for r, row in enumerate(grid):
        vals = set(row)
        if len(vals) == 1 and next(iter(vals)) != 0:
            samples[r] = row[0]
    if samples:
        for p in range(1, h+1):
            if all(samples[a] == samples[b] for a in samples for b in samples if (a-b) % p == 0):
                table = {r % p: v for r, v in samples.items()}
                return [[table.get(r % p, 0)] * w for r in range(h)]
    return [row[:] for row in grid]
